-- v5.24 close_anonymous_access ROLLBACK. EMERGENCY UNDO ONLY: it puts the logged-out data exposure back
-- (the public policies come back), so use it only if the app is broken for real users.
-- What it does, in one transaction: drops EVERY policy in schema public, then re-creates all 124 policies exactly as they were
-- before the change (the list below is v5.24_policies_before.sql). Written and checked before the change ran.
begin;
do $rb$
declare r record;
begin
  for r in select tablename, policyname from pg_policies where schemaname = 'public' loop
    execute format('drop policy %I on public.%I', r.policyname, r.tablename);
  end loop;
end
$rb$;
